import re

def trump_detector(text: str) -> float:
    vowels = 'aeiouAEIOU'
    lower_text = text.lower()

    total_vowels = 0
    extra_vowels = 0

    i = 0
    while i < len(lower_text):
        if lower_text[i] in 'aeiou':
            count = 1
            j = i + 1
            while j < len(lower_text) and lower_text[j] == lower_text[i]:
                count += 1
                j += 1

            total_vowels += count
            if count > 1:
                extra_vowels += count - 1

            i = j
        else:
            i += 1

    return round(extra_vowels / total_vowels, 2)
